//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS20700.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);
    $c.cm.PanelToGroupBox(panel_5);
    $c.cm.PanelToGroupBox(panel_4);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {

};

/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FROM_RCV_DD.setValue(vCurDate);
    edt_TO_RCV_DD.setValue(vCurDate);
    edt_FROM_ISUR_APPL_DD.setValue(vCurDate);
    edt_TO_ISUR_APPL_DD.setValue(vCurDate);
    edt_FROM_STD_CD_APPL_DD.setValue(vCurDate);
    edt_TO_STD_CD_APPL_DD.setValue(vCurDate);
    edt_FROM_STD_CD_APPL_DD_DEL.setValue(vCurDate);
    edt_TO_STD_CD_APPL_DD_DEL.setValue(vCurDate);
    edt_FROM_PROCS_DD.setValue(vCurDate);
    edt_TO_PROCS_DD.setValue(vCurDate);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    if (pFg == "ins_search") {
        dts_FaxLink.removeAll();
        dts_IsurAppl.removeAll();
        dts_StdCdAppl.removeAll();
        dts_DownIp.removeAll();
        dts_StdCdAppl_Del.removeAll();
        dts_IsurApplFaxLink.removeAll();
        dts_StdCdApplFaxLink.removeAll();
        dts_DownIpFaxLink.removeAll();
        dts_StdCdApplFaxLink_Del.removeAll();
        scwin.fn_SetGrdTitle("ins_Search");
    } else if (pFg == "ins_search1") {
        dts_IsurAppl.removeAll();
        dts_IsurApplFaxLink.removeAll();
        scwin.fn_SetGrdTitle("ins_Search1");
    } else if (pFg == "ins_search2") {
        dts_StdCdAppl.removeAll();
        dts_StdCdApplFaxLink.removeAll();
        scwin.fn_SetGrdTitle("ins_Search2");
    } else if (pFg == "ins_search3") {
        dts_DownIp.removeAll();
        dts_DownIpFaxLink.removeAll();
        scwin.fn_SetGrdTitle("ins_Search3");
    } else if (pFg == "ins_search4") {
        dts_StdCdAppl_Del.removeAll();
        dts_StdCdApplFaxLink_Del.removeAll();
        scwin.fn_SetGrdTitle("ins_Search4");
    } else if (pFg == "ins_searchLink1") {
        dts_IsurApplFaxLink.removeAll();
    } else if (pFg == "ins_searchLink2") {
        dts_StdCdApplFaxLink.removeAll();
    } else if (pFg == "ins_searchLink3") {
        dts_DownIpFaxLink.removeAll();
    } else if (pFg == "ins_searchLink4") {
        dts_StdCdApplFaxLink_Del.removeAll();
    }
};



/**
 * fax 목록조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_Search");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시
    //ShowWin(grd_FaxLink);

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listEtcFaxLinkInquiry1" + "&outputMessageId=INS_LIST_ETC_FAX_LINK_INQUIRY1" + "&param01=" + $c.stf.getObjectValue(edt_FROM_RCV_DD) + "&param02=" + $c.stf.getObjectValue(edt_TO_RCV_DD) + "&param03=" + $c.stf.getObjectValue(txb_TITLE);
    dts_FaxLink.DataID = encodeURI(url);
    dts_FaxLink.Reset();
};


