/**
 * 발행기관신청 파일 연결
 */
scwin.ins_FileLink1 = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("ins_FileLink1")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }

    // 저장 데이터 세팅.
    scwin.fn_SetInsertData("ins_FileLink1");
    trs_Save.Action = "/FaxInfoAction.do?method=registerEtcFaxLink1" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&queryId=lds.ins.etc.insert.registerEtcFaxLink1";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsurAppl)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Save.Post();
};


