/**
 * 발행기관신청 파일연결정보 삭제
 */
scwin.ins_Delete1 = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("ins_Delete1")) {
        return;
    }
    if (!confirm("삭제하시겠습니까?")) {
        return;
    }
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "ISUR_APPL_ID", dts_IsurApplFaxLink.getCellData(dts_IsurApplFaxLink.getRowPosition(), "ISUR_APPL_ID"));
    dts_Delete.setCellData(1, "FAX_IMG_FILE_NM", dts_IsurApplFaxLink.getCellData(dts_IsurApplFaxLink.getRowPosition(), "FAX_IMG_FILE_NM"));
    trs_Delete.Action = "/FaxInfoAction.do?method=removeEtcFaxLink1" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&queryId=lds.ins.etc.delete.removeEtcFaxLink1";
