scwin.ins_Delete4 = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("ins_Delete4")) {
        return;
    }
    if (!confirm("삭제하시겠습니까?")) {
        return;
    }
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
