};


/**
 * 파일 연결 시 입력 데이터 세팅
 */
scwin.fn_SetInsertData = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    var fax_img_file_nm = dts_FaxLink.getCellData(dts_FaxLink.getRowPosition(), "FAX_IMG_FILE_NM");
    if (pGubun == "ins_FileLink1") {
        for (var nRow = 1; nRow <= dts_IsurAppl.getTotalRow(); nRow++) {
            if (dts_IsurAppl.getCellData(nRow, "CHK") == "T") {
                dts_IsurAppl.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
    } else if (pGubun == "ins_FileLink2") {
        for (var nRow = 1; nRow <= dts_StdCdAppl.getTotalRow(); nRow++) {
            if (dts_StdCdAppl.getCellData(nRow, "CHK") == "T") {
                dts_StdCdAppl.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
    } else if (pGubun == "ins_FileLink3") {
        for (var nRow = 1; nRow <= dts_DownIp.getTotalRow(); nRow++) {
            if (dts_DownIp.getCellData(nRow, "CHK") == "T") {
                dts_DownIp.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
    } else if (pGubun == "ins_FileLink4") {
        for (var nRow = 1; nRow <= dts_StdCdAppl_Del.getTotalRow(); nRow++) {
            if (dts_StdCdAppl_Del.getCellData(nRow, "CHK") == "T") {
                dts_StdCdAppl_Del.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
    }
};





/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    if (pGubun == "ins_Search") {
        if ($c.stf.getObjectValue(edt_FROM_RCV_DD) == "") {
            $c.win.alert("접수시작일자를 입력하세요.");
            edt_FROM_RCV_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_RCV_DD) == "") {
            $c.win.alert("접수종료일자를 입력하세요.");
            edt_TO_RCV_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_RCV_DD, edt_TO_RCV_DD) == false) {
            return false;
        }
    } else if (pGubun == "ins_search1") {
        if ($c.stf.getObjectValue(edt_FROM_ISUR_APPL_DD) == "") {
            $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_ISUR_APPL_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_ISUR_APPL_DD) == "") {
            $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_ISUR_APPL_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_ISUR_APPL_DD, edt_TO_ISUR_APPL_DD) == false) {
            return false;
        }
    } else if (pGubun == "ins_search2") {
        if ($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) == "") {
            $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) == "") {
            $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_STD_CD_APPL_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD, edt_TO_STD_CD_APPL_DD) == false) {
            return false;
        }
    } else if (pGubun == "ins_search3") {
        if ($c.stf.getObjectValue(edt_FROM_PROCS_DD) == "") {
            $c.win.alert("등록시작일자를 입력하세요.");
            edt_FROM_PROCS_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_PROCS_DD) == "") {
            $c.win.alert("등록종료일자를 입력하세요.");
            edt_TO_PROCS_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_PROCS_DD, edt_TO_PROCS_DD) == false) {
            return false;
        }
    } else if (pGubun == "ins_search4") {
        if ($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD_DEL) == "") {
            $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_STD_CD_APPL_DD_DEL.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD_DEL) == "") {
            $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_STD_CD_APPL_DD_DEL.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD_DEL, edt_TO_STD_CD_APPL_DD_DEL) == false) {
            return false;
        }
    } else if (pGubun == "ins_searchLink1") {
        if (dts_IsurAppl.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun == "ins_searchLink2") {
        if (dts_StdCdAppl.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun == "ins_searchLink3") {
        if (dts_DownIp.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun == "ins_searchLink4") {
        if (dts_StdCdAppl_Del.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun == "ins_FileLink1") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getTotalRow() == 0) {
            $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        var nTrueCnt = 0;
        for (var nRow = 1; nRow <= dts_IsurAppl.getTotalRow(); nRow++) {
            if (dts_IsurAppl.getCellData(nRow, "CHK") == "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt == 0) {
            $c.win.alert("선택된 발행기관신청 정보가 없습니다.");
            return false;
        }
    } else if (pGubun == "ins_FileLink2") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowPosition() < 1) {
            $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        var nTrueCnt = 0;
        for (var nRow = 1; nRow <= dts_StdCdAppl.getTotalRow(); nRow++) {
            if (dts_StdCdAppl.getCellData(nRow, "CHK") == "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt == 0) {
            $c.win.alert("선택된 표준코드신청 정보가 없습니다.");
            return false;
        }
    } else if (pGubun == "ins_FileLink3") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowPosition() < 1) {
            $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        var nTrueCnt = 0;
        for (var nRow = 1; nRow <= dts_DownIp.getTotalRow(); nRow++) {
            if (dts_DownIp.getCellData(nRow, "CHK") == "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt == 0) {
            $c.win.alert("선택된 다운로드IP 정보가 없습니다.");
            return false;
        }
    } else if (pGubun == "ins_FileLink4") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowPosition() < 1) {
            $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        var nTrueCnt = 0;
        for (var nRow = 1; nRow <= dts_StdCdAppl_Del.getTotalRow(); nRow++) {
            if (dts_StdCdAppl_Del.getCellData(nRow, "CHK") == "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt == 0) {
            $c.win.alert("선택된 표준코드신청 정보가 없습니다.");
            return false;
        }
    }
    return true;
};


